// =============================================================================
// 5. COMMANDS & CHAT DOMAIN (~25 Values)
// =============================================================================

/// @brief Command execution permission levels.
enum class CommandPermissionLevel : int32_t {
    NORMAL                         = 0   , // Default player: regular non-privileged commands (/me, /msg)
    GAME_DIRECTORS                 = 1   , // Moderator / Builder permission level
    ADMIN                          = 2   , // Server operator: world and gameplay commands (/tp, /give, /gamemode)
    HOST                           = 3   , // World host / realm owner: cheat toggles and administrative control
    OWNER                          = 4   , // Server console / full system administrative permission
    INTERNAL                       = 5   , // Internal engine execution origin only (command blocks, scripts)
};

/// @brief Text message packet formatting modes for TextPacket.
enum class TextPacketType : uint8_t {
    RAW                            = 0   , // Unformatted raw text string
    CHAT                           = 1   , // Standard player chat message (<Player> Hello)
    TRANSLATE                      = 2   , // Localization translation key with replacement arguments
    POPUP                          = 3   , // Actionbar popup text displayed directly above hotbar
    JUKEBOX_POPUP                  = 4   , // Now Playing disc title popup
    TIP                            = 5   , // Bedrock loading screen or interaction tip text
    SYSTEM_MESSAGE                 = 6   , // Server system message ([Server] Restarting in 5m)
    WHISPER                        = 7   , // Private direct whisper message (/tell, /msg, /w)
    ANNOUNCEMENT                   = 8   , // Server-wide broadcast announcement (/say)
    TEXT_OBJECT                    = 9   , // Raw JSON text object containing styling and click events
    OBJECT_WHISPER                 = 10  , // Raw JSON text object sent as private whisper
};

/// @brief Command registration capability flags.
enum class CommandFlagValue : uint32_t {
    NONE                           = 0   , // No flags
    TEST_USAGE                     = 1   , // Command intended for test/dev environments
    HIDDEN_FROM_COMMAND_BLOCK      = 2   , // Command cannot be executed inside Command Blocks
    HIDDEN_FROM_PLAYER             = 4   , // Command hidden from regular player autocomplete
    HIDDEN_FROM_AUTOMATION         = 8   , // Command hidden from scripting/automation APIs
    LOCAL_CALL_ONLY                = 16  , // Command can only be executed locally
    DELEGATE                       = 32  , // Command delegates to external handler
};

// =============================================================================
// 6. NBT & TAG DOMAIN (~15 Values)
// =============================================================================

/// @brief Fundamental Bedrock NBT Tag polymorphic type IDs.
enum class TagType : uint8_t {
    End                            = 0   , // TAG_End sentinel terminating compound tag bodies
    Byte                           = 1   , // TAG_Byte signed 8-bit integer (boolean/byte)
    Short                          = 2   , // TAG_Short signed 16-bit integer
    Int                            = 3   , // TAG_Int signed 32-bit integer
    Int64                          = 4   , // TAG_Long signed 64-bit integer
    Float                          = 5   , // TAG_Float 32-bit IEEE 754 floating point
    Double                         = 6   , // TAG_Double 64-bit IEEE 754 double precision
    ByteArray                      = 7   , // TAG_Byte_Array length-prefixed array of 8-bit signed bytes
    String                         = 8   , // TAG_String UTF-8 length-prefixed string
    List                           = 9   , // TAG_List homogenous list of unnamed tags
    Compound                       = 10  , // TAG_Compound dictionary mapping names to polymorphic tags
    IntArray                       = 11  , // TAG_Int_Array length-prefixed array of 32-bit signed integers
};

// =============================================================================
// 7. STRUCTURES & WORLD TRANSFORM DOMAIN (~15 Values)
// =============================================================================

/// @brief Cardinal rotation angles for structure placement and block state transformations.
enum class Rotation : uint8_t {
    None                           = 0   , // No rotation (0 degrees)
    Rotate90                       = 1   , // 90 degrees clockwise rotation
    Rotate180                      = 2   , // 180 degrees rotation
    Rotate270                      = 3   , // 270 degrees clockwise rotation (90 counter-clockwise)
    Total                          = 4   , // Total rotation cardinal count
};

/// @brief Axial mirror reflections for structure placement.
enum class Mirror : uint8_t {
    None                           = 0   , // No reflection
    X                              = 1   , // Mirror along the X-axis (left-right reflection)
    Z                              = 2   , // Mirror along the Z-axis (front-back reflection)
    XZ                             = 3   , // Diagonal reflection along both axes
};

/// @brief Structure template storage categories.
enum class StructureTemplateType : uint8_t {
    Normal                         = 0   , // Standard in-memory structure template
    WorldGen                       = 1   , // Feature and jigsaw structure pool template
    Export                         = 2   , // Client / structure block export buffer
};

